-- Table structure for table `tb_borrow`
--

DROP TABLE IF EXISTS `tb_borrow`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_borrow` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `book_id` int NOT NULL,
  `borrow_date` date NOT NULL,
  `return_date` date DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `due_date` date DEFAULT NULL COMMENT '应还日期',
  `fine` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '罚金',
  `paid` tinyint NOT NULL DEFAULT '0' COMMENT '罚金0未付1已付',
  `overdue` int NOT NULL DEFAULT '0' COMMENT '逾期天数',
  `renewed` tinyint NOT NULL DEFAULT '0' COMMENT '是否续借',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `book_id` (`book_id`),
  KEY `idx_borrow_due` (`due_date`),
  CONSTRAINT `tb_borrow_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`),
  CONSTRAINT `tb_borrow_ibfk_2` FOREIGN KEY (`book_id`) REFERENCES `tb_book` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

