DROP TABLE IF EXISTS `tb_claim`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_claim` (
  `id` int NOT NULL AUTO_INCREMENT,
  `borrow_id` int NOT NULL,
  `user_id` int NOT NULL,
  `book_id` int NOT NULL,
  `report_date` date NOT NULL COMMENT '报失日期',
  `type` tinyint NOT NULL COMMENT '1原价 2折旧 3原书购买',
  `book_price` decimal(10,2) NOT NULL COMMENT '图书原价',
  `dep_rate` decimal(5,3) DEFAULT '1.000' COMMENT '折旧率',
  `amount` decimal(10,2) NOT NULL COMMENT '应赔金额',
  `paid` decimal(10,2) DEFAULT '0.00' COMMENT '实付',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待处理 1处理中 2已结案 3已驳回',
  `handle_by` int DEFAULT NULL COMMENT '处理人',
  `handle_remark` varchar(500) DEFAULT NULL,
  `pay_time` timestamp NULL DEFAULT NULL,
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `borrow_id` (`borrow_id`),
  KEY `book_id` (`book_id`),
  KEY `idx_claim_user` (`user_id`),
  KEY `idx_claim_status` (`status`),
  CONSTRAINT `tb_claim_ibfk_1` FOREIGN KEY (`borrow_id`) REFERENCES `tb_borrow` (`id`),
  CONSTRAINT `tb_claim_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`),
  CONSTRAINT `tb_claim_ibfk_3` FOREIGN KEY (`book_id`) REFERENCES `tb_book` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

