  `before` int NOT NULL,
  `after` int NOT NULL,
  `reason` varchar(200) NOT NULL COMMENT '按时还书/逾期/遗失赔偿/管理员调整',
  `op_by` int DEFAULT NULL COMMENT '管理员调整时填',
  `ref_type` varchar(50) DEFAULT NULL COMMENT 'BORROW/FINE/CLAIM/ADMIN',
  `ref_id` int DEFAULT NULL,
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_credit_user` (`user_id`),
  CONSTRAINT `tb_credit_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `tb_user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
